using System.Numerics;
namespace BobbyBoi;
sealed partial class Pet {
 Vector2 chaosAnchor,creeperFeet;float creeperAge,creeperHiss;int chaosResult;bool chaosReward;WorldEventKind? chaosNext;internal int? forcedChaosResult;readonly CharacterPose jailPose=new();
 void InitExpansion(){creeperFeet=new(x+Width/2+70,y+Height);}
 void ResetExpansionScene(){chaosNext=null;chaosReward=false;}
 void EndExpansion(){if(world.Active?.Spec.Kind>=WorldEventKind.Prison){actorInside=false;characterWorldScale=1;if(world.Active.Spec.Kind==WorldEventKind.Ufo){y=world.Active.Start.Y;vy=0;}}}
 Color SpeechAccent()=>world.Active?.Spec.Kind switch{WorldEventKind.Prison or WorldEventKind.Casino=>Color.FromArgb(239,179,73),WorldEventKind.Portal or WorldEventKind.Herobrine or WorldEventKind.Ufo=>Color.FromArgb(184,116,245),WorldEventKind.Earthquake=>Color.FromArgb(233,116,80),_=>Color.FromArgb(132,185,100)};
 Vector2 WorldShake=>world.Active?.Spec.Kind==WorldEventKind.Earthquake?new(MathF.Sin(worldAge*43)*5,MathF.Cos(worldAge*51)*3):Vector2.Zero;
 static readonly string[] Crimes=["illegal dirt trading","tax evasion","suspicious fishing","building without a permit","being broke in public","owning too many sticks","unlicensed diamonds"];
 void StartExpansion(WorldActivity a,Rectangle area){chaosAnchor=new(Math.Clamp(x+Width/2+110,area.Left+165,area.Right-165),area.Bottom-8);a.Target=new(chaosAnchor.X-Width/2-75,area.Bottom-Height);chaosResult=forcedChaosResult??rng.Next(4);forcedChaosResult=null;string line=a.Spec.Kind switch{WorldEventKind.Prison=>"ARRESTED: "+Crimes[rng.Next(Crimes.Length)],WorldEventKind.Casino=>"double or nothing",WorldEventKind.Portal=>"the nether has taxes",WorldEventKind.Herobrine=>"you saw that right",WorldEventKind.Earthquake=>"who mined below me",WorldEventKind.FakeUpdate=>"optimizing bread",WorldEventKind.AdoptCreeper=>"dog?",WorldEventKind.YouTube=>"yo guys. ignore the prison",WorldEventKind.Ufo=>"they asked about bread",_=>"mining my own business"};Say(line);}
 void FinishExpansion(){var next=chaosNext;CompleteWorld();if(next.HasValue&&data.World.Enabled(next.Value)&&WorldEligible(next.Value))world.Queue(next.Value);}
 void OnceChaos(Action reward){if(chaosReward)return;chaosReward=true;reward();SaveWorld();}
 void AdoptCreeper(){if(data.World.PetCreeper)return;if((wolf==null?0:1)>=data.World.CompanionLimit){Say("companion slots full");return;}data.World.PetCreeper=true;creeperFeet=new(x+Width/2+70,y+Height);Award("unsafe-friendship","Unsafe Friendship");SaveWorld();}
 void StepExpansion(WorldActivity a,float dt){StepExpansionSfx(a,dt);float t=a.Age;heldUntil=watch.Elapsed.TotalSeconds+1;
  switch(a.Spec.Kind){
   case WorldEventKind.FakeUpdate:
    Pose(t<4?Act.Sit:t<10?Act.Confused:Act.Hurt);if(t>5)OnceChaos(()=>Say("99 percent. zero hope"));if(t>13){AddWorldLoot("Update Debt Notice");Award("99-forever","99% Forever");Say("update complete. more debt installed");FinishExpansion();}break;
   case WorldEventKind.Cave:
    if(t<3){heldItem="Wooden Pickaxe";WalkWorld(a.Target,dt,130);}else if(t<8){actorInside=true;Pose(Act.Mine);if((int)(t*5)!=(int)((t-dt)*5)){worldParticles.Burst(chaosAnchor-new Vector2(0,35),Color.Gray,2);WorldAudio.Play("block",data.Volume);}}else{actorInside=false;heldItem="Diamond";Pose(Act.Celebrate);OnceChaos(()=>{AddWorldLoot(new[]{"Diamond","Coal","Iron","Redstone"}[chaosResult],chaosResult==0?1:3);Award("miner-life","Miner Life");Say(chaosResult==0?"why are his eyes like that":"i found rocks");if(chaosResult==0)chaosNext=WorldEventKind.Herobrine;data.World.LastStory="HEROBRINE IN MY TINY CAVE";});}if(t>12)FinishExpansion();break;
   case WorldEventKind.Herobrine:
    if(t<2)Pose(Act.Confused);else{FaceMotion(-1);Pose(Act.Run);x-=dt*60;}if(t>3)OnceChaos(()=>{Award("sighting","You Saw That Too, Right?");Say("this is not my save");});if(t>5.5f)FinishExpansion();break;
   case WorldEventKind.Casino:
    if(t<2)WalkWorld(a.Target,dt,120);else if(t<5){Pose(Act.Mine);heldItem="Emerald";}else{Pose(chaosResult==0?Act.Hurt:Act.Celebrate);OnceChaos(()=>{if(chaosResult==0){data.Items.TryGetValue("Emerald",out int balance);data.Items["Emerald"]=Math.Max(0,balance-64);Award("financial-ruin","Financial Ruin");Say("house always wins. lawyer.");chaosNext=WorldEventKind.Prison;}else{AddWorldLoot(chaosResult==1?"Dirt":"Bread");Say("i won one dirt. financially healed");}data.World.LastStory="I LOST EVERYTHING IN A CASINO";});}if(t>10)FinishExpansion();break;
   case WorldEventKind.Prison:
    if(t<3){Pose(Act.Confused);}else if(t<5){Pose(Act.Run);FaceMotion(-1);x-=dt*55;}else if(t<8)WalkWorld(new(chaosAnchor.X-Width/2,chaosAnchor.Y-Height+8),dt,220);else if(t<18){actorInside=true;Pose(t<12?Act.Confused:t<15?Act.Sit:Act.Mine);OnceChaos(()=>{Award("wrongful","Wrongfully Imprisoned");Say(data.World.PetCreeper?"tell my creeper i love him":"my bail is 64 emeralds");});}else{float exit=Math.Clamp((t-18)/2,0,1);x=chaosAnchor.X-Width/2+exit*130;y=Screen.FromPoint(new((int)x,(int)y)).WorkingArea.Bottom-Height;actorInside=t<20;Pose(t<20?Act.Walk:Act.Celebrate);if(t-dt<=18){if(data.World.PetCreeper){worldParticles.Burst(chaosAnchor,Color.LimeGreen,24);Say("my lawyer exploded");}else Say("released for good pixel behavior");}}if(t>21)FinishExpansion();break;
   case WorldEventKind.Portal:
    if(t<4){Pose(Act.Mine);heldItem="Obsidian";}else if(t<6){WalkWorld(new(chaosAnchor.X-Width/2,chaosAnchor.Y-Height),dt,180);}else if(t<10){actorInside=true;Pose(Act.Confused);if((int)(t*4)!=(int)((t-dt)*4))worldParticles.Burst(chaosAnchor-new Vector2(0,65),Color.MediumPurple,2);}else{actorInside=false;Pose(Act.Celebrate);OnceChaos(()=>{AddWorldLoot(new[]{"Blaze Rod","Nether Brick","Soul Sand","Suspicious Mushroom"}[chaosResult]);Award("nether","Into the Nether");Say("it smelled like lava and taxes");if(chaosResult==0)chaosNext=WorldEventKind.AdoptCreeper;else if(chaosResult==1)chaosNext=WorldEventKind.Herobrine;data.World.LastStory="THE NETHER HAS TAXES";});}if(t>15)FinishExpansion();break;
   case WorldEventKind.Earthquake:
    Pose(t<2?Act.Confused:Act.Hurt);if(t<.3f)OnceChaos(()=>{worldParticles.Burst(new(x+Width/2,y+Height-10),Color.Peru,24);if(data.World.HasHouse)data.World.HouseBlocks=Math.Max(1,data.World.HouseBlocks-4);Award("seismic","Seismic Issue");});if(t>5){Say("my house has negative durability");if(chaosResult==0)chaosNext=WorldEventKind.Cave;FinishExpansion();}break;
   case WorldEventKind.AdoptCreeper:Pose(Act.Wave);if(t>2)OnceChaos(()=>{AdoptCreeper();Say("this seems safe. probably");});if(t>5)FinishExpansion();break;
   case WorldEventKind.YouTube:
    if(t<2)WalkWorld(a.Target,dt,100);else Pose(t<5?Act.Wave:Act.Dance);if(t>8)OnceChaos(()=>{int followers=rng.Next(3,10);data.World.Subscribers=Math.Min(999999,data.World.Subscribers+followers);Award("creator","Content Creator");Say(data.World.PetCreeper?"stop hissing. we are LIVE":"three subscribers. im famous");CountWorld("videos");});if(t>11)FinishExpansion();break;
   case WorldEventKind.Ufo:
    Pose(t<3?Act.Confused:Act.Fall);if(t>=3&&t<7){y=a.Start.Y-Math.Clamp((t-3)/4,0,1)*150;characterWorldScale=1-(t-3)*.07f;}else if(t>=7&&t<11){actorInside=true;}else if(t>=11){actorInside=false;characterWorldScale=1;y=a.Start.Y-150*(1-Math.Clamp((t-11)/3,0,1));OnceChaos(()=>{AddWorldLoot("Cosmic Bread");Award("taken","Taken");Say("the aliens want a refund");data.World.LastStory="ALIENS TOOK MY BREAD";chaosNext=WorldEventKind.YouTube;});}if(t>16)FinishExpansion();break;
  }
 }
 void UpdateExpansionCompanion(float dt){if(!data.World.PetCreeper)return;creeperAge+=dt;creeperHiss+=dt;var target=new Vector2(x+Width/2+75,y+Height);if(!data.World.CreeperSitting){float dx=target.X-creeperFeet.X;creeperFeet.X+=Math.Clamp(dx,-dt*130,dt*130);}creeperFeet.Y=DesktopWorld.Floor(Screen.AllScreens.Select(s=>s.WorkingArea).ToArray(),creeperFeet.X,creeperFeet.Y,true);if(creeperHiss>24&&!world.Busy){creeperHiss=0;Sfx("confetti");worldParticles.Burst(creeperFeet-new Vector2(0,30),Color.LimeGreen,12);Say("confetti. not a war crime");}}
 void ExpansionMenu(){var m=new ToolStripMenuItem("Crime and bad decisions");foreach(var pair in new (string,WorldEventKind)[]{("Get Arrested",WorldEventKind.Prison),("Open Casino",WorldEventKind.Casino),("Build Nether Portal",WorldEventKind.Portal),("Herobrine Sighting",WorldEventKind.Herobrine),("Mini Earthquake",WorldEventKind.Earthquake),("Run Fake Update",WorldEventKind.FakeUpdate),("Adopt Pet Creeper",WorldEventKind.AdoptCreeper),("Record Tiny Video",WorldEventKind.YouTube),("Summon UFO",WorldEventKind.Ufo),("Go Cave Mining",WorldEventKind.Cave)})m.DropDownItems.Add(pair.Item1,null,(_,_)=>{menu.Close();RequestWorld(pair.Item2);});m.DropDownItems.Add("Pet Creeper: Sit / Follow",null,(_,_)=>{data.World.CreeperSitting=!data.World.CreeperSitting;SaveWorld();});m.DropDownItems.Add("Dismiss Pet Creeper",null,(_,_)=>{data.World.PetCreeper=false;SaveWorld();});menu.Items.Add(m);}
 void ExpansionSettings(FlowLayoutPanel panel){void Check(string text,bool value,Action<bool> apply){var c=new CheckBox{Text=text,Checked=value,Width=325,Height=30};c.CheckedChanged+=(_,_)=>{apply(c.Checked);if(world.Busy&&!data.World.Enabled(world.Active!.Spec.Kind))CancelWorld();SaveWorld();};panel.Controls.Add(c);}panel.Controls.Add(new Label{Text="CRIME AND BAD DECISIONS",Width=325,ForeColor=Color.Goldenrod});Check("Expansion events",data.World.Expansion,v=>data.World.Expansion=v);Check("Creepy Herobrine sightings",data.World.Creepy,v=>data.World.Creepy=v);Check("Prison, quake, UFO and fake update pranks",data.World.Pranks,v=>data.World.Pranks=v);Check("Performance mode (fewer visual frames)",data.World.PerformanceMode,v=>data.World.PerformanceMode=v);panel.Controls.Add(new Label{Text="Companion limit (wolf + pet creeper)",Width=325});var limit=new NumericUpDown{Minimum=1,Maximum=2,Value=data.World.CompanionLimit};limit.ValueChanged+=(_,_)=>{data.World.CompanionLimit=(int)limit.Value;if(limit.Value==1&&wolf!=null)data.World.PetCreeper=false;SaveWorld();};panel.Controls.Add(limit);}
}
